<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import Icon from '../components/Icon.vue'
import Chart from '../components/Chart.vue'
import {t,api,fmt,notify} from '../state'
const admin=ref<any>(null),email=ref(''),password=ref(''),error=ref(''),busy=ref(false),tab=ref('overview'),overview=ref<any>(null),users=ref<any[]>([]),audit=ref<any[]>([]),feedback=ref<any[]>([])
async function load(){[overview.value,users.value,audit.value,feedback.value]=await Promise.all([api('/ops/overview'),api('/ops/users'),api('/ops/audit'),api('/ops/feedback')])}
onMounted(async()=>{try{admin.value=await api('/ops/me');await load()}catch{}})
async function login(){busy.value=true;error.value='';try{admin.value=await api('/ops/login',{method:'POST',body:{email:email.value,password:password.value}});password.value='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function logout(){await api('/ops/logout',{method:'POST'});admin.value=null;overview.value=null}
async function suspend(u:any){try{await api('/ops/users/'+u.id,{method:'PATCH',body:{disabled:!u.disabled}});await load();notify(t('User access updated.','Доступ пользователя обновлён.'))}catch(e:any){notify(e.message,true)}}
const successRate=computed(()=>{const jobs=overview.value?.jobs.filter((j:any)=>['completed','failed'].includes(j.status))||[];return jobs.length?Math.round(jobs.filter((j:any)=>j.status==='completed').length/jobs.length*100):0})
const totalTokens=computed(()=>overview.value?.usage.reduce((s:number,u:any)=>s+u.tokens,0)||0)
const chartData=computed(()=>{const days=Array.from({length:7},(_,i)=>new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10));return{labels:days.map(d=>fmt(d)),datasets:[{label:'Tokens',data:days.map(d=>overview.value?.usage.filter((u:any)=>u.created_at.startsWith(d)).reduce((s:number,u:any)=>s+u.tokens,0)||0),backgroundColor:'#a24cb8',borderRadius:5,barPercentage:.5}]}})
</script>
<template><div class="ops-app"><header class="ops-header"><div class="brand"><span class="brand-symbol"><Icon name="AudioLines" :size="23"/></span>SignalDesk <span class="ops-label">OPERATIONS</span></div><div class="row gap-sm"><span class="small muted">{{t('Independent administrator access','Независимый административный доступ')}}</span><button v-if="admin" class="btn secondary small-btn" @click="logout"><Icon name="LogOut" :size="15"/>{{t('Sign out','Выйти')}}</button></div></header><div v-if="!admin" class="ops-login card"><span class="form-section-icon"><Icon name="ShieldCheck" :size="28"/></span><span class="eyebrow">OPERATIONS CONSOLE</span><h1>{{t('Administrator sign in','Вход администратора')}}</h1><p class="muted">{{t('This console uses separate accounts. Product workspace credentials are not accepted.','Здесь используются отдельные аккаунты. Учётные данные продукта не подходят.')}}</p><form @submit.prevent="login" class="form-stack"><label>{{t('Administrator email','Почта администратора')}}<input v-model="email" type="email" autocomplete="username" required></label><label>{{t('Password','Пароль')}}<input v-model="password" type="password" autocomplete="current-password" required minlength="10"></label><p v-if="error" class="notice error-notice" role="alert">{{error}}</p><button class="btn primary full" :disabled="busy"><Icon :name="busy?'LoaderCircle':'LockKeyhole'" :class="{spin:busy}" :size="17"/>{{t('Sign in to operations','Войти в управление')}}</button></form></div><main v-else-if="overview" class="ops-content"><div class="page-heading"><div><span class="eyebrow">{{t('SERVICE HEALTH & PRODUCT QUALITY','РАБОТА СЕРВИСА И КАЧЕСТВО ПРОДУКТА')}}</span><h1>{{t('The operational picture.','Операционная картина.')}}</h1><p>{{admin.email}} · {{t('Last refreshed','Обновлено')}} {{fmt(new Date().toISOString(),{timeStyle:'short'})}}</p></div><button class="btn secondary" @click="load"><Icon name="RefreshCw" :size="16"/>{{t('Refresh','Обновить')}}</button></div><div class="tabs page-tabs"><button v-for="s in [{id:'overview',en:'Overview',ru:'Обзор'},{id:'users',en:'Users',ru:'Пользователи'},{id:'jobs',en:'Analysis runs',ru:'Запуски анализа'},{id:'feedback',en:'Quality feedback',ru:'Отзывы о качестве'},{id:'audit',en:'Audit log',ru:'Журнал действий'}]" :key="s.id" :class="{active:tab===s.id}" @click="tab=s.id">{{t(s.en,s.ru)}}</button></div>
<template v-if="tab==='overview'"><div class="stats-grid"><article v-for="s in [{label:t('Users','Пользователи'),value:overview.users,icon:'Users',note:overview.verified_users+' '+t('verified','подтверждено')+' · '+(overview.guest_sessions||0)+' '+t('guest visits','гостевых посещений')},{label:t('Workspaces','Пространства'),value:overview.workspaces,icon:'Building2',note:overview.live_workspaces+' '+t('live workspaces','рабочих пространств')},{label:t('Published insights','Опубликовано выводов'),value:overview.events,icon:'Radar',note:t('Verified analyses from collected evidence','Проверенный анализ собранных материалов')},{label:t('Run completion','Успешность запусков'),value:successRate+'%',icon:'CheckCircle2',note:t('Recent completed / failed runs','По последним завершённым запускам')} ]" :key="s.label" class="stat-card"><div class="row between"><span>{{s.label}}</span><span class="stat-icon purple"><Icon :name="s.icon" :size="19"/></span></div><strong>{{s.value}}</strong><small>{{s.note}}</small></article></div><div class="dashboard-charts"><section class="card"><div class="card-heading"><div><h2>{{t('Model usage','Использование моделей')}}</h2><p>{{totalTokens.toLocaleString()}} {{t('tokens in recent 500 calls','токенов за последние 500 вызовов')}}</p></div><span class="badge neutral">{{t('Last 7 days','Последние 7 дней')}}</span></div><div class="chart-container"><Chart :data="chartData"/></div></section><section class="card"><h2>{{t('Quality & delivery','Качество и доставка')}}</h2><div class="ops-metric" v-for="(v,k) in overview.feedback" :key="k"><span>{{t({useful:'Useful feedback',irrelevant:'Irrelevant feedback',incorrect:'Incorrect analysis reports'}[k],{useful:'Полезные выводы',irrelevant:'Нерелевантные выводы',incorrect:'Сообщения об ошибках'}[k])}}</span><strong>{{v}}</strong></div><div class="form-divider"></div><div class="ops-metric" v-for="(v,k) in overview.email" :key="k"><span>{{t('Emails','Письма')}} · {{k}}</span><strong>{{v}}</strong></div><div class="service-status"><span :class="overview.model_configured?'live-dot':'alert-dot'"></span>{{t('Model configured','Модель настроена')}}: {{overview.model_configured?'✓':'—'}}</div><div class="service-status"><span :class="overview.email_enabled?'live-dot':'alert-dot'"></span>SendPulse: {{overview.email_enabled?t('Enabled','Включён'):t('Disabled','Отключён')}}</div></section></div></template>
<section v-else-if="tab==='users'" class="card table-card"><h2>{{t('Registered users','Зарегистрированные пользователи')}}</h2><div class="table-scroll"><table><thead><tr><th>{{t('User','Пользователь')}}</th><th>{{t('Joined','Регистрация')}}</th><th>{{t('Workspaces','Пространств')}}</th><th>{{t('Email','Почта')}}</th><th>{{t('Access','Доступ')}}</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.email}}</small></td><td>{{fmt(u.created_at,{dateStyle:'medium'})}}</td><td>{{u.workspace_count}}</td><td><span class="badge" :class="u.verified?'opportunity':'neutral'">{{u.verified?t('Verified','Подтверждена'):t('Unverified','Не подтверждена')}}</span></td><td><button class="btn small-btn" :class="u.disabled?'primary':'secondary'" @click="suspend(u)">{{u.disabled?t('Restore access','Восстановить'):t('Suspend','Приостановить')}}</button></td></tr></tbody></table></div></section>
<section v-else-if="tab==='jobs'" class="card table-card"><h2>{{t('Recent analysis runs','Последние запуски анализа')}}</h2><div class="table-scroll"><table><thead><tr><th>{{t('Run','Запуск')}}</th><th>{{t('Workspace','Пространство')}}</th><th>{{t('Status','Статус')}}</th><th>{{t('Started','Начало')}}</th><th>{{t('Result','Результат')}}</th></tr></thead><tbody><tr v-for="j in overview.jobs" :key="j.id"><td>{{j.kind}}<small>{{j.id.slice(0,8)}}</small></td><td>{{j.workspace_id.slice(0,8)}}</td><td><span class="status-badge" :class="j.status">{{j.status}}</span></td><td>{{fmt(j.created_at,{dateStyle:'short',timeStyle:'short'})}}</td><td><span v-if="j.error" class="source-error">{{j.error}}</span><span v-else>{{JSON.stringify(j.result)}}</span></td></tr></tbody></table></div></section>
<section v-else-if="tab==='feedback'" class="card"><h2>{{t('Feedback for quality review','Обратная связь для проверки качества')}}</h2><p class="small muted">{{t('Review incorrect-analysis reports first. Compare against evidence and company features before changing prompts or ranking thresholds.','Сначала проверяйте сообщения об ошибках. Сверяйте источники и признаки компании до изменения промптов и ранжирования.')}}</p><div v-for="f in feedback" :key="f.id" class="ops-feedback"><span class="badge" :class="f.rating==='useful'?'opportunity':'risk'">{{f.rating}}</span><p>{{f.comment||t('No comment provided','Без комментария')}}</p><span class="small muted">{{fmt(f.created_at)}} · {{f.workspace_id.slice(0,8)}} · {{f.event_id.slice(0,8)}}</span></div><div v-if="!feedback.length" class="empty compact-empty">{{t('No feedback submitted yet.','Отзывов пока нет.')}}</div></section>
<section v-else class="card table-card"><h2>{{t('Administrative & product audit','Журнал действий продукта и администраторов')}}</h2><div class="table-scroll"><table><thead><tr><th>{{t('Time','Время')}}</th><th>{{t('Action','Действие')}}</th><th>{{t('Actor','Участник')}}</th><th>{{t('Workspace','Пространство')}}</th><th>{{t('Detail','Детали')}}</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{fmt(a.created_at,{dateStyle:'short',timeStyle:'short'})}}</td><td>{{a.action}}</td><td>{{a.actor_id.slice(0,8)}}</td><td>{{a.workspace_id.slice(0,8)||'—'}}</td><td>{{JSON.stringify(a.detail)}}</td></tr></tbody></table></div></section></main></div></template>
